"""Turns research/results.json into research/TABLES.md."""
import json
from pathlib import Path

HERE = Path(__file__).parent
r = json.loads((HERE / "results.json").read_text())
usd = lambda v: f"{v:+,.0f}" if abs(v) >= 10 else f"{v:+,.1f}"
num = lambda v: f"{v:,.0f}" if isinstance(v, (int, float)) and not isinstance(v, bool) and abs(v) >= 100 else str(v)
out = ["# Sweep tables", "",
       "Generated by `run_sweep.py`. All money is USD per year for ONE market, after gas and infrastructure,",
       "median over 40 simulated years unless stated. These are model outputs, not measurements.", ""]


def row_table(title, rows, note=""):
    out.extend([f"## {title}", ""] + ([note, ""] if note else []))
    out.append("| Setting | Median net | Bad year (p10) | Good year (p90) | Loss years | Liquidations/yr | Tried | Won | Failed tx |")
    out.append("|---|---:|---:|---:|---:|---:|---:|---:|---:|")
    for name, s in rows:
        out.append(f"| {name} | {usd(s['median'])} | {usd(s['p10'])} | {usd(s['p90'])} | {s['p_loss']:.0%} | "
                   f"{s['events']:.0f} | {s['attempts']:.0f} | {s['wins']:.0f} | {s['failed']:.0f} |")
    out.append("")


def grid_table(title, g, row_name, col_name, note=""):
    out.extend([f"## {title}", ""] + ([note, ""] if note else []))
    out.append(f"| {row_name} \\ {col_name} | " + " | ".join(num(c) for c in g["cols"]) + " |")
    out.append("|---|" + "---:|" * len(g["cols"]))
    for name, cells in zip(g["rows"], g["cells"]):
        out.append(f"| {num(name)} | " + " | ".join(usd(c) for c in cells) + " |")
    out.append("")


b = r["base"]
out += ["## Base case", "", "Parameters: " + ", ".join(f"`{k}={v}`" for k, v in r["base_params"].items()), "",
        f"- Liquidation opportunities per year: {b['events']:.0f} (liquidated volume = {b['volume_pct']:.1f}% of market debt)",
        f"- Bot tries {b['attempts']:.0f}, wins {b['wins']:.0f}, pays for {b['failed']:.0f} failed transactions",
        f"- Net: median {usd(b['median'])}, bad year {usd(b['p10'])}, good year {usd(b['p90'])}, worst of 40 {usd(b['worst'])}",
        f"- Gas spent {b['gas']:.2f}; deepest run of losses on the gas wallet {b['drawdown']:.2f}; typical biggest single win {b['biggest_win']:.0f}",
        "- All 40 simulated years, sorted: " + ", ".join(str(v) for v in r["base_years"]), "",
        "### Where the money is (profit per opportunity before gas, base case)", "",
        "| Profit per liquidation | Share of opportunities | Share of total profit available |", "|---|---:|---:|"]
label = lambda h: ("loss-making" if h["hi"] <= 0 else f"over {h['lo']:.0f}" if h["hi"] > 1e9 else f"{max(h['lo'], 0):.0f} to {h['hi']:.0f}")
out += [f"| {label(h)} | {h['share']:.0%} | {h['value_share']:.0%} |" for h in r["profit_hist"]] + [""]

row_table("Competition scenarios", list(r["scenarios"].items()))
grid_table("Competition grid", r["grid_competition"], "Rival reaction time (s)", "Profit above which pros always win (USD)")
grid_table("Market size against professional attention", r["grid_size_pro"], "Market debt (USD)", "Pro threshold (USD)")
grid_table("Gas cost against professional attention", r["grid_gas_pro"], "Gas per tx (USD)", "Pro threshold (USD)")
grid_table("Bot settings, cheap gas (0.05 USD)", r["grid_bot_cheap"], "min_profit", "gas_safety")
grid_table("Bot settings, expensive gas (2 USD)", r["grid_bot_dear"], "min_profit", "gas_safety")

out += ["# One parameter at a time", "", "Everything else stays at the base case.", ""]
for key, rows in r["one_at_a_time"].items():
    row_table(f"`{key}`", [(num(s["value"]), s) for s in rows])

mc = r["mc"]
out += ["# Everything varied at once", "",
        f"{mc['n']} random combinations of all parameters (ranges in `sample_params`), 8 simulated years each.", "",
        f"- Loses money: {mc['p_loss']:.0%} of combinations",
        "- Median net by percentile: " + ", ".join(f"p{q} {usd(v)}" for q, v in mc["percentiles"].items()),
        "- Share of combinations earning more than: " + ", ".join(f"{float(t):,.0f} USD: {v:.0%}" for t, v in mc["share_over"].items()),
        f"- Mean {usd(mc['mean'])} (pulled up by a few large, uncontested markets)", "",
        "## Which parameters matter most (rank correlation with net profit)", "", "| Parameter | Correlation |", "|---|---:|"]
out += [f"| `{k}` | {v:+.2f} |" for k, v in mc["correlations"].items()] + [""]
out += ["## Conditions that separate winners from losers", "",
        "| Condition | Combinations | Median net | Lose money | Earn over 1,000 |", "|---|---:|---:|---:|---:|"]
out += [f"| {s['name']} | {s['n']} | {usd(s['median'])} | {s['p_loss']:.0%} | {s['over_1000']:.0%} |" for s in mc["splits"]] + [""]
(HERE / "TABLES.md").write_text("\n".join(out))
print("wrote TABLES.md")
